CREATE TABLE UnitsSold (product_id INTEGER, purchase_date TEXT, units INTEGER);

Output columns: product_id, average_price

CREATE TABLE Project (project_id INTEGER, employee_id INTEGER);
CREATE TABLE Employee (employee_id INTEGER, name TEXT, experience_years INTEGER);

Output columns: project_id, average_years

CREATE TABLE Users (user_id INTEGER, user_name TEXT);
CREATE TABLE Register (contest_id INTEGER, user_id INTEGER);

Output columns: contest_id, percentage

CREATE TABLE Sales (sale_id INTEGER, product_id INTEGER, year INTEGER, quantity INTEGER, price INTEGER);
CREATE TABLE Product (product_id INTEGER, product_name TEXT);

Output columns: product_id, first_year, quantity, price

